CREATE DATABASE IF NOT EXISTS student_task_manager CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_task_manager;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY, role ENUM('admin','dosen','mahasiswa') NOT NULL, username VARCHAR(50) UNIQUE NULL, name VARCHAR(150) NOT NULL, nim VARCHAR(30) UNIQUE NULL, nip VARCHAR(30) UNIQUE NULL, email VARCHAR(150) UNIQUE NULL, birth_date DATE NULL, must_change_password TINYINT(1) NOT NULL DEFAULT 0, password_hash VARCHAR(255) NOT NULL, class_name VARCHAR(30) NULL, study_program VARCHAR(100) NULL, status ENUM('active','inactive','pending') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE courses(id INT AUTO_INCREMENT PRIMARY KEY, code VARCHAR(20) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL, lecturer_id INT NOT NULL, semester TINYINT NOT NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(lecturer_id), FOREIGN KEY(lecturer_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE tasks(id INT AUTO_INCREMENT PRIMARY KEY, lecturer_id INT NOT NULL, course_id INT NOT NULL, code VARCHAR(30) UNIQUE NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, task_type ENUM('individu','kelompok') NOT NULL, assessment_type ENUM('project','quiz','laporan','presentasi','lainnya') NOT NULL, deadline DATETIME NOT NULL, status ENUM('active','closed') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(lecturer_id), INDEX(course_id), FOREIGN KEY(lecturer_id) REFERENCES users(id), FOREIGN KEY(course_id) REFERENCES courses(id)) ENGINE=InnoDB;
CREATE TABLE task_students(id INT AUTO_INCREMENT PRIMARY KEY, task_id INT NOT NULL, student_id INT NOT NULL, progress TINYINT NOT NULL DEFAULT 0, status ENUM('not_started','in_progress','completed') NOT NULL DEFAULT 'not_started', notes TEXT NULL, claimed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(task_id,student_id), INDEX(student_id), FOREIGN KEY(task_id) REFERENCES tasks(id), FOREIGN KEY(student_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE subtasks(id INT AUTO_INCREMENT PRIMARY KEY, task_student_id INT NOT NULL, title VARCHAR(200) NOT NULL, is_completed BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(task_student_id), FOREIGN KEY(task_student_id) REFERENCES task_students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE task_submissions(id INT AUTO_INCREMENT PRIMARY KEY, task_student_id INT UNIQUE NOT NULL, submitted_at DATETIME NOT NULL, status ENUM('submitted','late','graded') NOT NULL, grade TINYINT NULL, feedback TEXT NULL, graded_at DATETIME NULL, FOREIGN KEY(task_student_id) REFERENCES task_students(id)) ENGINE=InnoDB;
CREATE TABLE submission_files(id INT AUTO_INCREMENT PRIMARY KEY, submission_id INT NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL, file_type VARCHAR(100) NOT NULL, file_size INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(submission_id), FOREIGN KEY(submission_id) REFERENCES task_submissions(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE attachments(id INT AUTO_INCREMENT PRIMARY KEY, task_id INT NOT NULL, original_name VARCHAR(255) NOT NULL, stored_name VARCHAR(255) NOT NULL, file_type VARCHAR(100) NOT NULL, file_size INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(task_id), FOREIGN KEY(task_id) REFERENCES tasks(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, type VARCHAR(50) NOT NULL, message VARCHAR(255) NOT NULL, link VARCHAR(255) NULL, is_read BOOLEAN NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(100) NOT NULL, description VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE login_attempts(identity_hash CHAR(64) PRIMARY KEY, window_started_at TIMESTAMP(3) NOT NULL, attempts TINYINT UNSIGNED NOT NULL, INDEX(window_started_at)) ENGINE=InnoDB;
